// ─── TUNNEL API ───
app.get('/api/tunnel', (req, res) => {
  if (tunnelInfo && tunnelInfo.state === 'ready' && tunnelInfo.url) {
    res.json({
      success: true,
      status: 'ready',
      url: tunnelInfo.url,
      type: tunnelInfo.type,
      startedAt: tunnelInfo.startedAt
    });
  } else {
    res.json({
