   const scrollEl = document.createElement('div');
   scrollEl.className = 'term-scroll';
   scrollEl.innerHTML = '<div class="term-mouse-pad" title="Виртуальная мышь: тянуть — прокрутка, тап сверху/снизу — шаг">🖱</div><div class="term-mouse-wheel"><button class="term-scroll-arr up">▲</button><button class="term-scroll-arr down">▼</button></div><button class="term-scroll-handle" title="Потянуть — переместить мышь; тап — вернуть наверх">⠿</button>';
   wrap.appendChild(scrollEl);
   panel.appendChild(wrap);
   const cdEl = document.createElement('div');
   cdEl.className = 'term-cd';
   cdEl.id = 'cd-' + id;
   panel.appendChild(cdEl);
   document.getElementById('term-container').appendChild(panel);

   term.open(termEl);
   fitTerm(tab);
   tab.scroll = attachTermScroll(id, panel, term);
   tab.touchHandler = setupTermTouch(termEl, term);

   const connect = () => {
     hideCountdown(id);
     const socket = new WebSocket(`${protocol}//${location.host}/ws`);
     tab.socket = socket;
     // Watchdog: a connection attempt stuck in CONNECTING (stalled tunnel) would
     // otherwise hang the tab forever — no open, no close. Force it closed so
     // the reconnect path takes over.
     if (tab.connectTimer) { clearTimeout(tab.connectTimer); tab.connectTimer = null; }
     tab.connectTimer = setTimeout(() => {
       if (tab.socket === socket && socket.readyState === WebSocket.CONNECTING) {
         try { socket.close(); } catch {}
       }
     }, 8000);

     socket.onopen = () => {
       if (tab.connectTimer) { clearTimeout(tab.connectTimer); tab.connectTimer = null; }
       tab.lastPong = Date.now();
       tab.retry = 0;
       tab.disconnected = false;
       hideCountdown(id);
       if (activeTab?.id === id) fitTerm(tab);
       socket.send(JSON.stringify({ type: 'open', toolId: isPlain ? '_terminal' : effectiveToolId, sessionId: id, cwd,
         repoPath: (resume && resume.repoPath) || null, emulator: (resume && resume.emulator) || null,
         phoneRunner: (resume && resume.phoneRunner) || null, cols: term.cols, rows: term.rows }));
       if (!isTouch) term.focus();
     };

     socket.onmessage = (e) => {
       let m;
       try { m = JSON.parse(e.data); } catch { return; }
       if (m.type === 'pong') { tab.lastPong = Date.now(); return; }
       if (m.type === 'output' && m.id === id) { term.write(m.data); }
       if (m.type === 'exit') {
         term.write(`\r\n\x1b[33m[Exited ${m.code} — нажми ⟲, чтобы перезапустить]\x1b[0m\r\n`);
         termRecoverShow('⚠ Сессия завершилась — перезапустите агента');
         renderSidebar();
       }
       if (m.type === 'error') term.write(`\r\n\x1b[31m[Error: ${m.error}]\x1b[0m\r\n`);
     };

     socket.onerror = () => {
       // Some Android WebViews emit error without a useful close reason. Force
       // the close path so the existing reconnect/backoff logic always runs.
       try { if (socket.readyState !== WebSocket.CLOSED) socket.close(); } catch {}
     };
     socket.onclose = (ev) => {
       if (tab.manualClose) return;
       // The close code is the whole diagnosis. 1006 means the peer vanished
       // without a close frame (dead connector, dropped radio); 1001 is the page
       // going away; anything else carries a reason worth reading. Without this
       // line every drop looks identical from the outside.
       console.warn(`[hub] terminal socket closed code=${ev && ev.code}` +
         `${(ev && ev.reason) ? ` reason="${ev.reason}"` : ''}` +
         ` wasClean=${ev ? ev.wasClean : '?'} retry=${tab.retry}` +
         ` silent=${Math.round((Date.now() - (tab.lastPong || Date.now())) / 1000)}s`);
       if (tab.socket !== socket) return; // superseded by a newer socket; it owns reconnection
       if (tab.connectTimer) { clearTimeout(tab.connectTimer); tab.connectTimer = null; }
       if (tab.reconnectTimer) { clearTimeout(tab.reconnectTimer); tab.reconnectTimer = null; }
       tab.disconnected = true;
       // Exponential backoff with jitter — fast while flapping, gentle on hiccups.
       const delay = Math.min(3000 * Math.pow(2, tab.retry), 30000) + Math.round(Math.random() * 400);
       tab.retry = Math.min(tab.retry + 1, 6);
       showCountdown(id, delay);
       tab.reconnectTimer = setTimeout(connect, delay);
     };
   };
   tab.connect = connect;
   connect();

   // Keepalive: ping/pong + forced close when the socket goes stale (>60s).
   // Pings are throttled by Chrome in background — therefore we also fire
   // one immediately when the page becomes visible again (wake-up call).
   let keepaliveIdle = 0;
   tab.keepAlive = setInterval(() => {
     if (tab.manualClose || !tab.socket) return;
     if (tab.socket.readyState === WebSocket.OPEN) {
       if (Date.now() - tab.lastPong > 60000) {
         // stale — force reconnect from client side
         tab.socket.close();
       } else if (document.hidden) {
         // в фоне просто считаемIdle, пинг отправим при wake-up
         keepaliveIdle++;
         if (keepaliveIdle > 8) { // ~120s без пинга во фоне — прогоняем reconnect
           tab.socket.close();
         }
       } else {
         // на перед планке — отправляем пинг и сбрасываемIdle-счетчик
         tab.socket.send(JSON.stringify({ type: 'ping' }));
         keepaliveIdle = 0;
       }
     }
   }, 15000);

 // Wake-up: когда пользователь возвращается в приложение — сразу шлем ping
 // и перезапускаем переподключение, если соединение умерло во фоне.
 document.addEventListener('visibilitychange', () => {
   if (!document.hidden && tab.socket && tab.socket.readyState === WebSocket.OPEN) {
     tab.socket.send(JSON.stringify({ type: 'ping' }));
     tab.reconnectTimer = setTimeout(() => {}, 0); // чистим таймер реконнекта
     keepaliveIdle = 0;
   }
 });

   term.onData((data) => {
     termSendInput(tab.socket, data);
   });

   term.onResize(({ cols, rows }) => {
     // Дегенеративный размер (fit нулевой/скрытой ширины) в tmux не шлём:
     // раньше он реально сужал сессию до узкой щели, которая так в ней
     // и оставалась после восстановления связи.
     if (cols < 20 || rows < 3) return;
     if (tab.socket && tab.socket.readyState === WebSocket.OPEN) tab.socket.send(JSON.stringify({ type: 'resize', cols, rows }));
   });

   tab.resizeObs = new ResizeObserver(() => { if (activeTab?.id === id) fitTerm(tab); });
   tab.resizeObs.observe(panel);

   switchTab(id);
 }

 function renderTabs() {
   document.getElementById('tabs').innerHTML = tabs.map(t => `
     <div class="tab ${activeTab?.id === t.id ? 'on' : ''}" onclick="switchTab('${t.id}')">
       <span class="tab-dot" style="background:${t.toolColor}"></span>
       <span>${t.toolIcon} ${t.toolName}</span>
       <span class="tab-x" onclick="event.stopPropagation();closeTab('${t.id}')">✕</span>
     </div>
   `).join('') + `<div class="tab-add" onclick="showNewTermModal()">+</div>`;
 }

 function fitTerm(tab) {
   if (!tab || !tab.fitAddon || !tab.term) return;
   const panel = document.getElementById('panel-' + tab.id);
   if (panel && panel.offsetParent === null) return; // скрыта — fit сожмёт в щелочку
   tab.fitAddon.fit();
 }

 function switchTab(id) {
   activeTab = tabs.find(t => t.id === id);
   document.querySelectorAll('.tab').forEach((el, i) => el.classList.toggle('on', tabs[i]?.id === id));
   document.querySelectorAll('.term-panel').forEach(p => p.classList.remove('on'));
   const panel = document.getElementById('panel-' + id);
   if (panel) panel.classList.add('on');
   if (activeTab) setTimeout(() => {
     fitTerm(activeTab);
     if (!isTouch) activeTab.term?.focus();
     activeTab.scroll?.upd?.();
   }, 50);
   renderSidebar();
 }

 function closeTab(id) {
   const idx = tabs.findIndex(t => t.id === id);
   if (idx === -1) return;
   const t = tabs[idx];
   t.manualClose = true;
   // Closing a tab must end the server-side session, not just detach: a leftover
   // tmux session is re-attached on the next page load (/api/sessions), so closed
   // tabs came back and kept piling up. 'kill' terminates it for good.
   try { if (t.socket && t.socket.readyState === 1) t.socket.send(JSON.stringify({ type: 'kill' })); } catch {}
   // HTTP fallback: the tab may be mid-reconnect, when a WS frame cannot be sent.
   try { fetch('/api/sessions/' + encodeURIComponent(id) + '/kill', { method: 'POST' }).catch(() => {}); } catch {}
   if (t.keepAlive) clearInterval(t.keepAlive);
   if (t.cdTimer) clearInterval(t.cdTimer);
   if (t.resizeObs) t.resizeObs.disconnect();
   if (t.scroll?.destroy) t.scroll.destroy();
   if (t.touchHandler?.destroy) t.touchHandler.destroy();
   t.socket?.close();
   t.term?.dispose();
   document.getElementById('panel-' + id)?.remove();
   tabs.splice(idx, 1);
   if (activeTab?.id === id) activeTab = tabs[Math.min(idx, tabs.length - 1)] || null;
   if (activeTab) switchTab(activeTab.id);
   renderTabs();
   renderSidebar();
   persistOpenTabs();
 }

