   if (!_fsm) return Promise.resolve(null);
   return _fsm.get('list', key).then(r => {
     if (!r || !r.body) return null;
     try { return { json: JSON.parse(r.body) }; } catch (e) { return null; }
   }).catch(() => null);
 }
