     const j = await r.json().catch(() => null);
     if (j && j.success) {
       try { fsmPutBlob(fmBackend + '|' + p, new Blob([ta.value], { type: 'text/plain' })); } catch (e) {}
       if (btn) { btn.textContent = '✓ Сохранено'; setTimeout(() => { btn.textContent = '💾 Сохранить'; btn.disabled = false; }, 1400); }
