 function ttsSetRate(v){ ttsRate=parseFloat(v)||1; const l=document.getElementById('tts-rate-label'); if(l) l.textContent=v+'×'; const ld=document.getElementById('tts-rate-label-desk'); if(ld) ld.textContent=v+'×'; }
