       try { packet = opusEnc.encode(frame, opusFrameSamples); } catch { continue; }
       if (!packet || !packet.length) continue;
       lastSentAt = Date.now();
       try { ws.send(Buffer.from(packet), { binary: true }); } catch { stop(); break; }
     }
