       if (codec === 'opus') sendOpus(); else sendAudio(true);
       if (!closed && code && ws.readyState === 1) {
         try { ws.send(JSON.stringify({ type: 'error', error: 'аудиозахват завершился: ' + code })); } catch {}
       }
