  try {
    const r = await fetch(`https://api.github.com/repos/${repo}/git/trees/${treeSha}?recursive=1`, { headers: ghHeaders(), signal: AbortSignal.timeout(20000) });
    if (r.ok) {
      const j = await r.json();
      if (Array.isArray(j.tree)) {
        for (const e of j.tree) {
          if (e.type === 'blob' && typeof e.size === 'number') map.set('snapshots/' + stamp + '/' + e.path, e.size);
        }
      }
      if (j.truncated) { /* sizes we got are still right, some are missing */ }
    }
  } catch (e) {}
  wbSizeCache.set(treeSha, map);
  if (wbSizeCache.size > 64) wbSizeCache.delete(wbSizeCache.keys().next().value);
  return map;
};
