          }
        }
      }
    }
  } catch (e) { /* no sizes this round; the listing still stands */ }
  wbSizeCache.set(treeSha, map);
  if (wbSizeCache.size > 96) wbSizeCache.delete(wbSizeCache.keys().next().value);
  return map;
};

